                       context.getEvaluator().extendsClass(node, "android.content.ContentProvider", false) ||
                       context.getEvaluator().extendsClass(node, "android.content.BroadcastReceiver", false)) {
                       isComponent = true;
                   }

                   if (!isComponent) return;

                   // Check manifest registration
                   if (!isRegistered(context, qualifiedName)) {
                       context.report(ISSUE, node, context.getLocation(node),
                           "Class is not registered in the manifest");
                   }
               }
           };
       }

       private boolean isRegistered(JavaContext context, String qualifiedName) {
           File manifest = context.getMainProject().getManifest();
           if (manifest == null || !manifest.exists()) return false; // Or true? If no manifest, can't register. Assume false to report, or true to avoid noise. Let's return false.

