               DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
               factory.setNamespaceAware(true);
               DocumentBuilder builder = factory.newDocumentBuilder();
               Document doc = builder.parse(manifest);
               Element root = doc.getDocumentElement();
               String pkg = root.getAttribute("package");

               // Check <activity>, <service>, <provider>, <receiver>
               String[] tags = {"activity", "service", "provider", "receiver"};
               for (String tag : tags) {
                   NodeList nodes = root.getElementsByTagName(tag);
                   for (int i = 0; i < nodes.getLength(); i++) {
                       Element el = (Element) nodes.item(i);
                       String name = el.getAttributeNS("http://schemas.android.com/apk/res/android", "name");
                       if (name != null && !name.isEmpty()) {
                           String fullName = name;
                           if (name.startsWith(".")) {
                               fullName = pkg + name;
                           } else if (!name.contains(".")) {
                               fullName = pkg + "." + name;
                           }
                           if (fullName.equals(qualifiedName)) {
                               return true;
                           }
                       }
                   }
               }
           } catch (Exception e) {
               // Ignore parse errors
           }
           return false;
       }
