                if (!isRegistered(context, qualifiedName, isActivity, isService, isProvider)) {
                    String type = isActivity ? "Activity" : (isService ? "Service" : "ContentProvider");
                    context.report(ISSUE, node, context.getLocation(node),
                            "The <" + type.toLowerCase() + "> " + node.getName() + " is not registered in the manifest");
                }
            }
        };
    }

    private boolean isRegistered(JavaContext context, String className, boolean isActivity, boolean isService, boolean isProvider) {
        File manifest = context.getMainProject().getManifest();
        if (manifest == null || !manifest.exists()) {
            return false;
        }

